\label{lem:lambda}
Let $G$ be $2$-transitive on $\mathcal{P}$, $|\mathcal{P}|=v$, and let $\mathcal{T}$ be an orbit of $G$ on $\binom{\mathcal{P}}{3}$, $\mathcal{O}\in\mathcal{T}$.
\begin{enumerate}
\item $|\mathcal{T}|=|G|/|G_{\mathcal{O}}|$.
\item The pair $\{x,y\}\subseteq\mathcal{P}$ lies in exactly $\lambda=6|G|/\bigl(|G_{\mathcal{O}}|\,v(v-1)\bigr)$ blocks of $\mathcal{T}$;  since $G$ is $2$-transitive on pairs, this number is independent of the pair, and $(\mathcal{P},\mathcal{T})$ is automatically a simple $2$-$(v,3,\lambda)$ design whose automorphism group contains $G$;  in particular the displayed expression for $\lambda$ is an integer;  indeed $\lambda$ is by definition the number of blocks of $\mathcal{T}$ through a given pair, a cardinality, hence an integer, and the displayed formula merely re-expresses it.
\item Distinct $G$-orbits yield distinct block sets, although the resulting designs may be abstractly isomorphic.
\end{enumerate}

\label{prop:each-orbit}
Let $G$ be $2$-transitive on $\mathcal{P}$, $v=|\mathcal{P}|$, and $\mathcal{T}$ a $G$-orbit on $\binom{\mathcal{P}}{3}$ with representative $\mathcal{O}$.  Then $(\mathcal{P},\mathcal{T})$ is an orbit triple system \textup{(}\textup{Definition \ref{def:orbit-ts}}\textup{)}, a simple $2$-$(v,3,\lambda_\mathcal{T})$ design with
\[
\lambda_\mathcal{T}=\frac{6|\mathcal{T}|}{v(v-1)}=\frac{6|G|}{|G_{\mathcal{O}}|\,v(v-1)}
\]
\textup{(}\textup{Lemma \ref{lem:lambda}\textup{(}2\textup{)}}\textup{)}.

\label{cor:all-invariant}
Let $G$ be $2$-transitive on $\mathcal{P}$ with $r$ orbits on $\binom{\mathcal{P}}{3}$.  The nonempty $G$-invariant simple triple systems on $\mathcal{P}$ are exactly $\mathcal{D}_I=(\mathcal{P},\mathcal{T}_I)$, $\varnothing
\ne I\subseteq\{1,\ldots,r\}$, with parameter $\lambda_I=\sum_{i\in I}\lambda_i$;  there are exactly $2^r-1$ of them.  Distinct unions are distinct block sets even when their parameters coincide;  $G\le\operatorname{Aut}(\mathcal{D}_I)$ for every $I$, with equality not asserted in general;  two different groups may yield the same block set, and two different choices of $I$ may yield isomorphic designs.  The classification is thus of $G$-invariant block sets together with their parameters, not necessarily a classification up to abstract design isomorphism.

\label{thm:2trans}
Let $G$ be a finite $2$-transitive permutation group of degree $v\ge4$ with socle $S=soc(G)$.  The list below is a list of permutation representations; accidental isomorphisms between socles (such as $PSL(3,2)\congPSL(2,7)$) do not constitute additional actions.
\begin{enumerate}
\item \textbf{\textup{(}Affine type\textup{)}} $S=V$ is elementary abelian of order $p^d$ \textup{(}$p$ prime\textup{)}, $G=V\rtimes G_0$, $G_0\le\operatorname{GL}(d,p)$ transitive on $V\setminus\{0\}$.  By Hering's theorem \cite{hering1985} one of the following holds, with $p^d=q^a$ etc.\ as indicated:
  \begin{enumerate}
  \item $G_0\le \operatorname{\Gamma L}(1,p^d)$ \textup{(}soluble type; $G$ contains a sharply $2$-transitive subgroup; the Huppert classification applies\textup{)};
  \item $\operatorname{SL}(a,q)\trianglelefteq G_0\le\operatorname{\Gamma L}(a,q)$ with $p^d=q^a$, $a\ge2$;
  \item $Sp(2a,q)\trianglelefteq G_0\le\GammaSp(2a,q)$ with $p^d=q^{2a}$, $a\ge2$;
  \item $G_2'(q)\trianglelefteq G_0$ with $p=2$, $p^d=q^6$ \textup{(}where $G_2'(2)\congPSU(3,3)$, and $G_2'(q)=G_2(q)$ for $q>2$\textup{)};
  \item the exceptional cases with $G_0$ one of the groups in \textup{Table \ref{tab:hering}}, acting on $V=\mathbb{F}_q^d$.
  \end{enumerate}
\item \textbf{\textup{(}Almost simple type\textup{)}} $S=T$ is nonabelian simple and $T\le G\le\operatorname{Aut}(T)$.  The possibilities are:
  \begin{enumerate}
  \item $T=PSL(2,q)$ \textup{(}$q\ge4$\textup{)}, acting on the $q+1$ points of $\mathrm{PG}(1,q)$, and $G\leP\string\Gamma L(2,q)$;
  \item $T=PSL(n,q)$ \textup{(}$n\ge3$, $q$ a prime power\textup{)}, acting on the $v=(q^n-1)/(q-1)$ points of the projective space $\mathrm{PG}(n-1,q)$, and $G\leP\string\Gamma L(n,q)$ \textup{(}the extension by the diagonal and field automorphisms\textup{)};  this action is $2$-transitive since the stabilizer of a point is \textup{(}the projective image of\textup{)} a parabolic subgroup, which is transitive on the remaining points;
  \item $T=Sp(2n,2)=\Omega(2n+1,2)$ \textup{(}$n\ge3$\textup{)}, acting $2$-transitively on the $v=2^{2n-1}\pm 2^{n-1}$ points of each of the two halves of the nonsingular quadric \textup{(}the two orbits of $\Omega(2n+1,2)$ on the nonsingular points of $\mathrm{PG}(2n,2)$\textup{)};
  \item $T=PSU(3,q)$ \textup{(}$q\ge3$\textup{)}, acting on the $q^3+1$ points of the Hermitian unital, and $G\leP\string\Gamma U(3,q)$;
  \item $T=Sz(q)$ \textup{(}$q=2^{2m+1}>2$\textup{)}, acting on the $q^2+1$ points of the Suzuki ovoid, and $G\leSz(q)\cdot(2m+1)$;
  \item $T=Ree(q)=^2G_2(q)$ \textup{(}$q=3^{2m+1}>3$\textup{)}, acting on the $q^3+1$ points of the Ree unital, and $G\leRee(q)\cdot(2m+1)$;
  \item $T=Alt(n)$ \textup{(}$n\ge5$\textup{)}, natural action, $G=Alt(n)$ or $G=Sym(n)$ \textup{(}$n=6$ also allowed:  the exceptional outer automorphism of $Alt(6)$ does not give a $2$-transitive degree-$6$ action with socle $Alt(6)$ different from the natural one\textup{)};
  \item $T$ sporadic:  $T\in\{M_{11},M_{12},M_{22},M_{23},M_{24}\}$ \textup{(}with the standard actions of degrees $11,12,22,23,24$\textup{)}, or $T\in\{HS,Co_3\}$ with the $2$-transitive actions of degrees $176,276$ respectively; for the Mathieu groups $M_{12},M_{22}$ the group $G$ may also be $M_{12}.2$, $M_{22}.2$.  \textup{(}The groups $\operatorname{Suz}$, $\mathrm{Fi}_{22}$ and $J_1$ are \emph{not} $2$-transitive in any of their usual actions:  indeed $|\operatorname{Suz}|/(1782\cdot1781)$, $|\mathrm{Fi}_{22}|/(14080\cdot14079)$ and $|J_1|/(266\cdot265)$ are not integers, so the two-point stabilizer arithmetic excludes them.  For $\operatorname{Suz}$ of degree $1782$ \textup{(}point stabilizer $G_2(4)$\textup{)} and $\mathrm{Fi}_{22}$ of degree $14080$ the actions are rank $3$.\textup{)}
  \end{enumerate}
  \textup{(}The group $PSU(3,2)\cong 3^2{:}Q_8$ of degree $9$ has elementary abelian socle and belongs to the affine type:  it is the sharply $2$-transitive group attached to the nearfield of order $9$, treated in \textup{Section \ref{sec:affine}} and in \textup{Table \ref{tab:verify}}.\textup{)}
\end{enumerate}

For the almost simple analysis in the following sections we repeatedly need the outer automorphism groups of the classical groups involved.  These are standard facts; we record here the ones used in the analysis below:
\begin{enumerate}
\item $\operatorname{Out}(PSL(2,q))\cong C_f$ for $q$ even, and $\cong C_2\times C_f$ for $q=p^f$ odd \textup{(}the diagonal part $D$ is trivial for $q$ even, then $PGL(2,q)=PSL(2,q)$, and is $C_2$ for $q$ odd\textup{)};
\item $\operatorname{Out}(PSU(3,q))\cong C_{(3,q+1)}\times C_{2f}$, the diagonal \textup{(}graph\textup{)} part of order $(3,q+1)$ and the field part of order $2f$;  then $PGU(3,q)/PSU(3,q)\cong C_{(3,q+1)}$ and $P\string\Gamma U(3,q)/PSU(3,q)\cong C_{(3,q+1)}\times C_{2f}$;
\item $\operatorname{Out}(Sz(q))\cong C_{2m+1}$ and $\operatorname{Out}(Ree(q))\cong C_{2m+1}$ \textup{(}field automorphisms\textup{)};
\item $\operatorname{Out}(Alt(n))\cong C_2$ for $n
\ne6$ \textup{(}with $Sym(n)=Alt(n).2$\textup{)}, and $\operatorname{Out}(Alt(6))\cong C_2\times C_2$.
\end{enumerate}
These data will be used throughout \textup{Sections \ref{sec:psl2}--\ref{sec:ree}} and \textup{Section \ref{sec:as}} without further comment.

\label{lem:suborbit}
Let $G$ be $2$-transitive on $\Omega$ and fix $P=\{\alpha,\beta\}$. The map
\[
x\longmapsto\{\alpha,\beta,x\}
\]
induces a surjection from the $G_P$-orbits on $\Omega\setminus P$ onto the $G$-orbits on $\binom{\Omega}{3}$: every triple contains a pair, and by $2$-transitivity on points $G$ is transitive on unordered pairs, so every $G$-orbit of triples contains a triple of the form $\{\alpha,\beta,x\}$.  For a triple orbit $X$ let $H=\overline{G}_X\le S_3$ be the induced image of the setwise stabilizer of a representative triple.  Then the number of $G_P$-suborbits lying over $X$, that is, the number of $G_P$-orbits on the set $\{T\in X^{G}: P\subseteq T\}$ of triples of the orbit containing $P$, equals the number of $H$-orbits on the three two-subsets of $X$.  Consequently this number is $3,2,1,1$ for $H=1,C_2,C_3,S_3$, respectively:  a trivial image gives three suborbits over $X$, a transposition-only image $C_2$ gives two, and an image containing a $3$-cycle ($H=C_3$ or $S_3$) gives exactly one.  In particular the suborbit map is a bijection if and only if every triple orbit has image containing a $3$-cycle.

\label{prop:pair-orbits}
Let $G$ be $2$-transitive on $\mathcal{P}$, $v\ge4$, and fix an unordered pair $P=\{\alpha,\beta\}$ with setwise stabilizer $G_P=G_{\{\alpha,\beta\}}$.  The assignment
\[
\gamma^{G_P}\longmapsto \{\alpha,\beta,\gamma\}^{G}
\]
is a well-defined surjection from the set of $G_P$-orbits on $\mathcal{P}\setminus P$ onto the set of $G$-orbits on $\binom{\mathcal{P}}{3}$.  The fiber over the orbit of $X=\{\alpha,\beta,\gamma\}$ is in bijection with the $G_P$-orbits on the set $\{T\in X^{G}: P\subseteq T\}$ of triples of the orbit containing the pair $P$;  in particular the map is a bijection if and only if $G_P$ is transitive on the triples of each $G$-orbit that contain $P$.  In double-coset terms, the $G_P$-orbits on $X^{G}\cong G/G_X$ correspond to the double cosets $G_P\backslash G/G_X$, and the triples containing $P$ correspond to those double cosets whose representative $g$ satisfies $g^{-1}(P)\subseteq X$.

$PGL(2,q)$ is sharply $3$-transitive, so the image of $S_{\mathcal{O}}$ in $S_3$ consists of those permutations of $\mathcal{O}$ realizable by an element of $PSL(2,q)$;  the kernel is trivial (a projective transformation fixing three points is the identity).  Normalize $\mathcal{O}=\{0,1,\infty\}$ (possible inside $PGL$).  The transposition fixing $\infty$ and swapping $0,1$ is the involution $t\mapsto1-t$, represented by the matrix $\begin{pmatrix}-1&1\\0&1\end{pmatrix}$ of determinant $-1$;  hence a transposition lies in $PSL(2,q)$ iff $-1$ is a square in $\mathbb{F}_q^{\times}$, i.e.\ iff $q$ is even or $q\equiv1\pmod4$.  A $3$-cycle on the reference triple is realized by $t\mapsto1/(1-t)$, an element of determinant $1$ (\textup{Lemma \ref{lem:sqclass}}), which lies in $PSL(2,q)$ for every $q\ge3$ (for $q=3$, $PSL(2,3)\cong A_4$ on $4$ points and $S_{\mathcal{O}}\cong C_3$).
\begin{enumerate}
\item $q$ even:  $-1=1$ is a square, transpositions and $3$-cycles exist:  image $S_3$.
\item $q\equiv3\pmod4$:  $-1$ is a non-square, so no transposition exists on any $\mathcal{O}$ (a transposition would require $-1$ to be a square, \textup{Lemma \ref{lem:sqclass}});  the image of $S_{\mathcal{O}}$ in $S_3$ is therefore contained in $C_3$.  For the reference triple $\Delta=\{0,1,\infty\}$ the $3$-cycle $(0\,1\,\infty)$ is realized by $t\mapsto1/(1-t)$, an element of determinant $1$ lying in $PSL(2,q)$ (\textup{Lemma \ref{lem:sqclass}}), so $|S_{\Delta}|=3$.  Stabilizers of triples in the same $S$-orbit are conjugate, hence the orbit of $\Delta$ has size $|S|/|S_{\Delta}|=q(q^2-1)/6=\binom{q+1}{3}$, the total number of $3$-subsets of $\mathcal{P}$.  Since this equals $\bigl|\binom{\mathcal{P}}{3}\bigr|$, the orbit is all of $\binom{\mathcal{P}}{3}$:  $PSL(2,q)$ is $3$-homogeneous, and $S_{\mathcal{O}}\cong C_3$ with $|S_{\mathcal{O}}|=3$ for every $\mathcal{O}$.  The two determinant classes of \textup{Lemma \ref{lem:sqclass}} are fused into this single orbit.  The square-class label is not well defined in this case:  the $PGL(2,q)$-stabilizer of a triple contains a transposition of nonsquare determinant, so representatives of the two determinant classes are $PSL(2,q)$-conjugate;  instead, the orbit-size calculation above directly proves that $PSL(2,q)$ is $3$-homogeneous.
\item $q\equiv1\pmod4$:  transpositions exist;  the two square classes are the two orbits (transitivity on each class is classical, cf.\ \cite{huppert1967,dixon1996});  on each, image $S_3$.  The square class attached to an element $g\inPGL(2,q)$ with $g(\mathcal{O}_0)=\mathcal{O}$ is well defined:  if $h(\mathcal{O}_0)=\mathcal{O}$ as well, then $h^{-1}g$ stabilizes $\mathcal{O}_0$ setwise, and its image in $S_3$ is realized inside $PSL(2,q)$ (transpositions and $3$-cycles both lie in $PSL(2,q)$ here), while the pointwise kernel is trivial;  hence $h^{-1}g\inPSL(2,q)$ and $g,h$ have the same determinant square class.
\end{enumerate}

\label{cor:psl2-designs}
Each listed system is simple, its blocks being three-point subsets (not a multiset family).  The triple systems with point set $\mathrm{PG}(1,q)$ and automorphism group containing $PSL(2,q)$ are:
\begin{enumerate}
\item $q$ even:  one system, $2$-\mbox{$(q+1,3,q-1)$} \textup{(}all $3$-subsets;  $\lambda=q-1$ by \eqref{eq:lambda}\textup{)};
\item $q\equiv3\pmod4$:  one system, again $2$-\mbox{$(q+1,3,q-1)$} \textup{(}all $3$-subsets\textup{)};
\item $q\equiv1\pmod4$:  two orbit triple systems \textup{(}the two square classes of \textup{Theorem \ref{thm:psl2}\textup{(}3\textup{)}}\textup{)}, each with $\lambda=(q-1)/2$;  their union is the complete system on $\mathrm{PG}(1,q)$, with $\lambda=(q-1)/2+(q-1)/2=q-1$ \textup{(}\textup{Proposition \ref{prop:union-orbits}}\textup{)}.
\end{enumerate}
\textup{(}For $q=4$:  $\lambda=q-1=3$:  the complete $2$-$(5,3,3)$ design on $5$ points, with $PSL(2,4)\cong A_5$.\textup{)}

\label{thm:pgl}
Let $PSL(2,q)\le G\leP\string\Gamma L(2,q)$, $q=p^f$, and let $\mathcal{O}$ be a $3$-subset of $\mathrm{PG}(1,q)$; here and below $G_{\mathcal{O}}$ and $G_{(\mathcal{O})}$ denote the setwise and the pointwise stabilizer of $\mathcal{O}$, respectively.
\begin{enumerate}
\item If $G=PGL(2,q)$:  $G_{\mathcal{O}}\cong S_3$, $G_{(\mathcal{O})}=1$, for all $\mathcal{O}$;  single orbit on $\binom{\mathcal{P}}{3}$.
\item If $G\supsetneqPGL(2,q)$, let $F\le C_f$ be the \textup{(}cyclic\textup{)} group of field automorphisms contained in $G$ (i.e.\ the image of $\mathrm{Gal}(\mathbb{F}_q/\mathbb{F}_p)$ in $\mathrm{Aut}(\mathbb{F}_q)$, or a subgroup of that image, acting naturally on $\mathrm{PG}(1,q)$).  Then $G$ is transitive on $\binom{\mathcal{P}}{3}$ and for \emph{every} $3$-subset $\mathcal{O}$,
\[
G_{\mathcal{O}}=G_{(\mathcal{O})}\rtimes S_3,\qquad |G_{\mathcal{O}}|=6\,|F|,\qquad |G_{(\mathcal{O})}|=|F|.
\]
The kernel $G_{(\mathcal{O})}$ consists of the elements $g_\sigma=h_\sigma\circ\sigma$ \textup{(}$\sigma\in F$\textup{)}, where $h_\sigma\inPGL(2,q)$ is the unique projective transformation with $h_\sigma(\sigma(x))=x$ for $x\in\mathcal{O}$;  in particular the elements of the kernel need not be field automorphisms and exist for \emph{all} $\mathcal{O}$ \textup{(}they are the ``twisted'' elements fixing the three points\textup{)}.
\end{enumerate}

\label{thm:psl2-field}
Let $q=p^f$ and $G=PSL(2,q)\cdot F$ with $1
\ne F\le C_f$ a cyclic group of field automorphisms acting on $\mathrm{PG}(1,q)$ ($F$ the image of $\mathrm{Gal}(\mathbb{F}_q/\mathbb{F}_p)$, or a subgroup of that image); let $\mathcal{O}$ be a $3$-subset, with $G_{\mathcal{O}}$ and $G_{(\mathcal{O})}$ its setwise and pointwise stabilizers.  Then $|G_{(\mathcal{O})}|=|F|$ for every $\mathcal{O}$ \textup{(}the twisted kernel elements as in \textup{Theorem \ref{thm:pgl}\textup{(}2\textup{)}}, now with $h_\sigma\inPSL(2,q)$:  this holds because for $q\equiv3\pmod4$ the map $h_\sigma$ has square determinant automatically, and for $q\equiv1\pmod4$ or $q$ even it is the square-type choice\textup{)}, and the image in $S_3$ is as in \textup{Theorem \ref{thm:psl2}}:
\begin{enumerate}
\item $q$ even:  single orbit, image $S_3$, $|G_{\mathcal{O}}|=6|F|$;
\item $q\equiv3\pmod4$:  single orbit, image $C_3$, $|G_{\mathcal{O}}|=3|F|$;
\item $q\equiv1\pmod4$:  two orbits, image $S_3$, $|G_{\mathcal{O}}|=6|F|$ on each.
\end{enumerate}

\label{cor:psln-designs}
With $v=(q^n-1)/(q-1)$:
\begin{enumerate}
\item $n=3$:  the collinear orbit gives $2$-\mbox{$(q^2+q+1,3,q-1)$} and the non-collinear orbit gives $2$-\mbox{$(q^2+q+1,3,q^2)$};
\item $n\ge4$:  the collinear orbit gives $2$-\mbox{$(v,3,q-1)$} --- for $q=2$ this is the Steiner triple system $\mathrm{STS}(2^n-1)$ on the lines of $\mathrm{PG}(n-1,2)$ --- and the non-collinear orbit gives $2$-\mbox{$(v,3,v-1-q)$}.
\end{enumerate}
By \textup{Proposition \ref{prop:union-orbits}} the union of the two orbits is the complete system $2$-$(v,3,v-2)$ on projective space:  for $n=3$, $\lambda=q-1+q^2=q^2+q-1=v-2$;  for $n\ge4$, $\lambda=q-1+v-1-q=v-2$.
\textup{(}The values follow from \eqref{eq:lambda} and \textup{Theorem \ref{thm:psln}};  e.g.\ $PSL(3,3)$ on $13$ points:  $\lambda=2,9$;  $PSL(4,2)=Alt(8)$ on $15$:  $\lambda=1,12$;  $PSL(3,5)$ on $31$:  $\lambda=4,25$;  $PSL(5,2)$ on $31$:  $\lambda=1,28$;  $PSL(4,3)$ on $40$:  $\lambda=2,36$;  $PSL(6,2)$ on $63$:  $\lambda=1,60$.\textup{)}

\label{prop:psu-diag}
Let $q\ge3$, $d=\gcd(3,q+1)$, and let $PGU(3,q)$ act on the Hermitian unital $\mathcal{U}$.  For every $q$,
\[
\sigma_3(PGU(3,q),\mathcal{U})
=\begin{cases}
\dfrac{q+3}{2}, & q\ \text{odd},\\[4pt]
\dfrac{q+2}{2}, & q\ \text{even}.
\end{cases}
\]
When $d=3$ this is the fusion count of the $S$-orbits on triples under the diagonal overgroup $PGU(3,q)/S\cong C_3$, obtained from the fusing of the $S$-orbits sharing a $\delta$-orbit, where $\delta\inPGU(3,q)\setminus S$ is the diagonal element of order $3$ \textup{(cf.\ \textup{Theorem \ref{thm:pgu}(1)}}\textup{)};  no fusion occurs for $d=1$, and then $(q+3)/2$ resp.\ $(q+2)/2$ coincides with the $d=1$ closed forms $\sigma_3(PSU(3,q))=(q+3)/2$ resp.\ $1+q/2$ of \textup{Theorem \ref{thm:main-psu}(3)} \textup{(the diagonal overgroup equals $S$ for $d=1$)}\textup{)}.  In particular $q=2$ gives $\sigma_3(PGU(3,2))=2$ \textup{(Table \ref{tab:psu-general})}.

\label{prop:psu-even}
Let $q=2^{2m+1}>2$, so that $d=\gcd(3,q+1)=3$, and let $S=PSU(3,q)$ act on the
Hermitian unital $\mathcal{U}$.  Then
\begin{enumerate}
\item the setwise pair stabilizer $G_{\{\alpha,\beta\}}$ has exactly $3q/2$
suborbits off the block $B$ (of length $2(q^2-1)/3$), and none is fixed by $\tau$ as
a set;
\item the non-collinear three-point orbits of $S$ comprise $(q-2)/2$ orbits of
$C_3$-type (setwise stabilizer of order $3$, $\lambda=2(q^2-1)/3$) and $(q+1)/3$
orbits of trivial stabilizer ($\lambda=2(q^2-1)$);
\item $\sigma_3(S,\mathcal{U})=1+\tfrac{q-2}{2}+\tfrac{q+1}{3}=\tfrac{5q+2}{6}$.
\end{enumerate}
The values are verified for $q=8,32$ in \textup{Chapter \ref{sec:verify}}.

\label{prop:psu-odd}
Let $q$ be odd with $d=\gcd(3,q+1)=3$, and let $S=PSU(3,q)$ act on the Hermitian
unital $\mathcal{U}$.  Then
\begin{enumerate}
\item the setwise pair stabilizer $G_{\{\alpha,\beta\}}$ has exactly $3$ fixed
suborbits off the block $B$ (of length $(q^2-1)/3$, image $S_3$) and, off $B$,
$(q-5)/2$ merged $C_3$-suborbits and $q+1$ trivial suborbits;
\item the non-collinear three-point orbits of $S$ comprise $3$ orbits of $S_3$-type
(setwise stabilizer of order $6$, $\lambda=(q^2-1)/3$), $(q-5)/2$ orbits of
$C_3$-type (order $3$, $\lambda=2(q^2-1)/3$), and $(q+1)/3$ orbits of trivial
stabilizer ($\lambda=2(q^2-1)$);
\item $\sigma_3(S,\mathcal{U})=1+3+\tfrac{q-5}{2}+\tfrac{q+1}{3}
=\tfrac{5q+11}{6}$.
\end{enumerate}
The values are verified for $q=5,11,17,23$ in \textup{Chapter \ref{sec:verify}}.

\label{prop:psu-computed}
Let $S=PSU(3,q)$, $d=\gcd(3,q+1)$, and let the non-collinear triple orbits be classified by the order of the setwise stabilizer $S_{\mathcal{O}}$ \textup{(}$6$, $3$ or $1$, with trivial pointwise stabilizer in every case, by \textup{Lemma \ref{lem:psu-pointwise}}\textup{)}.  The multiplicities are, for $q\le49$:
\begin{center}
\resizebox{0.95\textwidth}{!}{$\begin{array}{c|c|c|c}
 & q\ \text{odd},\ d=1 & q\ \text{odd},\ d=3 & q\ \text{even} \\ \hline
\#\ \text{orbits with stabilizer }6\ (S_3\text{-image}) & 1 & 3\ \text{(proved)} & 0 \\
\#\ \text{orbits with stabilizer }3\ (C_3\text{-image}) & (q-1)/2 & (q-5)/2\ \text{(proved)} & q/2\ \text{(d=1)},\quad (q-2)/2\ \text{(d=3,\ proved)} \\
\#\ \text{orbits with stabilizer }1 & 0 & (q+1)/3\ \text{(proved)} & 0\ \text{(d=1)},\quad (q+1)/3\ \text{(d=3,\ proved)}
\end{array}$}
\end{center}
where in the last column the $d=1$ case means all $q/2$ merged orbits have image $C_3$ \textup{(}verified for $q=4,16$\textup{)};  for $d=3$ the even-$q$ multiplicities are proved for every $q=2^{2m+1}$ in \textup{Proposition \ref{prop:psu-even}} ($(q-2)/2$ and $(q+1)/3$), while the odd-$d=3$ multiplicities are proved for every $q$ with $3\mid q+1$ in \textup{Proposition \ref{prop:psu-odd}} ($3$, $(q-5)/2$ and $(q+1)/3$).  The present proposition records the small-$q$ computational refinement (for $q=8$ there are $3$ $C_3$-orbits and $3$ trivial orbits, and the trivial suborbits $3q/2-3=9$ fuse three-to-one;  for $q=32$ the values are $15$ and $11$, and the stabilizer orders and $\lambda$-values are listed in \textup{Table \ref{tab:magma}}\textup{)};  the exceptional value $q=2$ is listed separately in \textup{Table \ref{tab:magma}}.  These values are finite computations \textup{(Magma and GAP, \textup{Chapter \ref{sec:verify}}}\textup{)} covering $q\le49$;  together with \textup{Theorem \ref{thm:main-psu}(2)} and \textup{Propositions \ref{prop:psu-odd} and \ref{prop:psu-even}} they give the closed forms of \textup{Theorem \ref{thm:main-psu}(3)} in every row:  the $d=1$ rows for every $q$, the odd-$d=3$ row by \textup{Proposition \ref{prop:psu-odd}}, and the even-$d=3$ row by \textup{Proposition \ref{prop:psu-even}}.

\label{thm:pgu}
Let $S\le G\leP\string\Gamma U(3,q)$, $d=(3,q+1)$, and $\mathcal{O}\in\binom{\mathcal{U}}{3}$.
\begin{enumerate}
\item \textbf{Diagonal overgroup.}  If $G=PGU(3,q)$ \textup{(}$d>1$\textup{)}:
  \begin{enumerate}
  \item collinear $\mathcal{O}$:  $G_{\mathcal{O}}\cong\mathbb{Z}_{q+1}\rtimes S_3$, $|G_{\mathcal{O}}|=6(q+1)$, $G_{(\mathcal{O})}\cong\mathbb{Z}_{q+1}$ \textup{(}the kernel is the preimage of $\mathbb{Z}_{(q+1)/d}$ under the quotient by the diagonal element of order $3$\textup{)};
  \item non-collinear $\mathcal{O}$:  the image in $S_3$ is as in \textup{Theorem \ref{thm:main-psu}} for $S$;  additionally, if $3\mid q+1$ the diagonal element $\delta\inPGU(3,q)\setminus S$ of order $3$ acts on the unital with $3$-cycles $\{[x:y:z],[x:y:\zeta z],[x:y:\zeta^2 z]\}$ for suitable coordinates and $\zeta^{q+1}=1$ primitive \textup{(explicit coordinate proof, see below}\textup{)};  if $\mathcal{O}$ is such a $3$-cycle then $G_{\mathcal{O}}$ contains $\delta$ and the image contains $C_3$.  The fusion picture is now settled for every $q$:  $\sigma_3(PGU(3,q),\mathcal{U})=(q+3)/2$ for $q$ odd and $(q+2)/2$ for $q$ even \textup{(Proposition \ref{prop:psu-diag}}\textup{)} \textup{(for $d=1$ the overgroup equals $S$, and these values coincide with the $d=1$ closed forms of \textup{Theorem \ref{thm:main-psu}(3)})}, so $PGU(3,q)$ fuses exactly $(3q-1)/2$ of the $S$-orbits for $q$ odd and $q-1$ of them for $q$ even \textup{(including $q=2$, where $\sigma_3(PGU(3,2))=2$)}.
  \end{enumerate}
\item \textbf{Field overgroup.}  If $G=S\rtimes C_{f'}$ \textup{(}$f'\mid f$, field automorphisms only\textup{)}:  field automorphisms fix pointwise the sub-unital over the subfield $\mathbb{F}_{p^{f/f'}}$;  if $\mathcal{O}$ lies in that sub-unital then $G_{(\mathcal{O})}$ contains the corresponding field automorphisms \textup{(}a cyclic group\textup{)};  the image in $S_3$ is unchanged from \textup{Theorem \ref{thm:main-psu}} \textup{(}field automorphisms preserve collinearity and the orbit types, since they conjugate $S$ to itself and normalize the unital\textup{)}.  For $q=3^a$ the full field part is cyclic of order $2f$, generated by the Frobenius $\sigma_p\colon[x:y:z]\mapsto[x^p:y^p:z^p]$;  its unique order-$2$ element is the conjugation $\sigma\colon[x:y:z]\mapsto[x^q:y^q:z^q]$, for which the GAP computation of \textup{Table \ref{tab:psu-pgu}} in the range $q=3,9,27$ verifies cycle type $1^{q+1}2^{q(q^2-1)/2}$ on the $q^3+1$ points and fixes every suborbit as a set, hence every $S$-orbit on triples as a set, so the conjugation alone causes no fusion.  By \textup{Proposition \ref{prop:psu-field-nofusion}} the conjugation is proved not to fuse for every $q\ge3$;  the full field part $C_{2f}$ (generated by $\sigma_p$) may fuse for $f>1$ \textup{(Remark \ref{rem:psu-field})}.
\item \textbf{Full overgroup.}  $G=P\string\Gamma U(3,q)$:  by the general reduction of \textup{Proposition \ref{prop:outer}}, $S_{\mathcal{O}}\le G_{\mathcal{O}}$ and $G_{\mathcal{O}}/S_{\mathcal{O}}$ embeds into $P\string\Gamma U(3,q)/S$.  For $q=3^a$ with $d=1$, $PGU(3,q)=S$ and $P\string\Gamma U(3,q)/S$ is the field part $C_{2f}$, generated by the Frobenius $\sigma_p$ of order $2f$;  its unique order-$2$ element is the conjugation $\sigma_q=\sigma_p^f$, which alone causes no fusion for every $q\ge3$ (Proposition~\ref{prop:psu-field-nofusion}), while the full field part $C_{2f}$ fuses for $f>1$ (Remark~\ref{rem:psu-field}).  In particular
\[
\sigma_3(P\string\Gamma U(3,q),\mathcal{U})=\sigma_3(PSU(3,q),\mathcal{U})=\frac{q+3}{2}
\]
holds for $q=3$ ($f=1$, field part $C_2$), and the computed values $\sigma_3(P\string\Gamma U(3,q))=4,7$ obtain for $q=9,27$.  The diagonal part is proved in \textup{Proposition \ref{prop:psu-diag}} and the field part $C_{f'}$ fixes pointwise the sub-unital over the subfield and preserves collinearity and the orbit types \textup{((2))}, but its fusion of $S$-orbits on triples outside the sub-unital is not claimed \textup{(Remark \ref{rem:psu-field})}.
\end{enumerate}

\label{rem:psu-z-a}
The non-collinear orbits carry two coordinate parametrizations, related as follows.  In the standard coordinates of \textup{Proposition \ref{prop:psu-diag}} the third point is $R(x,y)=\langle(x,y,1)\rangle$ \textup{($y
\ne 0$, $x+\bar x+y\bar y=0$)}, with $u=y\bar y\in\mathbb{F}_q^{\times}$ and $z=x/u\in\mathcal Z=\{z\in K:z+\bar z=-1\}$.  Under the isometry $(X_0,X_1,X_2)\mapsto(X_0,X_2,X_1)$ of the coordinate convention and normalization of the first coordinate to $1$, the same point reads $\gamma=(1,u',z')$ with $u'=x^{-1}$, $z'=yx^{-1}$ \textup{($\mathrm{Tr}_{K/F}(u')+N_{K/F}(z')=(x+\bar x+y\bar y)/(x\bar x)=0$, so $\gamma\in\mathcal{U}\setminus B$}\textup{)}, and the $PSU(3,q)$-splitting parameter of \textup{Lemma \ref{lem:psu-c3}} is
\[
a=\frac{\bar u'}{u'}=u'^{q-1}=(uz)^{-(q-1)}=z^{-(q-1)}\in K^1,
\]
the factor $u^{q-1}=1$ vanishing because $u\in\mathbb{F}_q^{\times}$.  Hence:
\begin{itemize}
\item the diagonal pairing $\iota\colon z\mapsto-1-z$ \textup{($=\bar z$ for $z\in\mathcal Z$)} of \textup{Proposition \ref{prop:psu-diag}} acts on $a$ as $a\mapsto\bar a=a^{-1}$ \textup{(}since $a\in K^1$\textup{)}:  the non-collinear $PGU(3,q)$-orbits are exactly the reversal classes $\{a,a^{-1}\}$, as used in \textup{Proposition \ref{prop:psu-field-nofusion}};
\item the Frobenius $\sigma_p$ acts as $z\mapsto z^p$ and $a\mapsto a^p$, and the conjugation $\sigma_q$ as $z\mapsto z^q$ and $a\mapsto a^q=a^{-1}$ \textup{(Remark \ref{rem:psu-field})};
\item the $PSU(3,q)$-split of a non-collinear orbit is governed by $a\in(K^1)^3$ \textup{(Lemma \ref{lem:psu-c3})}, and the two coordinate systems realize the same split:  $a\in(K^1)^3 \iff z^{-(q-1)}\in(K^1)^3$.
\end{itemize}

\label{thm:sz}
Let $S=Sz(q)$, $q=2^{2m+1}>2$, acting on the Suzuki ovoid with $v=q^2+1$, and $\mathcal{O}$ a $3$-subset.
\begin{enumerate}
\item The pointwise stabilizer of any $3$-subset is trivial:  $S_{(\mathcal{O})}=1$.
\item If the three points lie on a common Suzuki circle \textup{(}an orbit of a sub-Suzuki subgroup $Sz(q_0)$, $q_0=2^{2m'+1}$, on the ovoid, equivalently a sub-ovoid of the Suzuki ovoid\textup{)}, then $S_{\mathcal{O}}\cong C_2$;  if the three points do not lie on a Suzuki circle, then $S_{\mathcal{O}}=1$ \textup{(classical geometric input, \cite{suzuki1962}}\textup{)}.
\item In particular $S_{\mathcal{O}}$ is never $S_3$ or $C_3$:  since $3
\nmid|S|$, no element of order $3$ exists, and the image in $S_3$ is contained in a $C_2$.
\item The circle triples form a single $S$-orbit \textup{(classical geometric input, \cite{suzuki1962}}\textup{)}.  The triples not on a circle form $\frac{q-2}{6}$ further orbits \textup{(Theorem \ref{thm:sz-orbits})}, each with trivial setwise stabilizer \textup{(by (2)}\textup{)}.  The two-orbit structure for $q=8$ is verified independently in \textup{Table \ref{tab:verify}} \textup{(Proposition \ref{prop:sz8-computed})}.
\end{enumerate}

\label{thm:sz-orbits}
Let $S=Sz(q)$, $q=2^{2m+1}>2$, act on the $q^2+1$ points of the Suzuki ovoid.  The number of $S$-orbits on three-subsets is
\[
\boxed{\;\sigma_3(S)=\frac{q+4}{6}\;}
\]
with $\sigma_3(Sz(q))$ integral since $q=2^{2m+1}\equiv2\pmod6$.  Consequently the circle class is the single orbit of \textup{Theorem \ref{thm:sz}(4)} and the generic class consists of $\frac{q+4}{6}-1=\frac{q-2}{6}$ orbits, each with trivial setwise stabilizer \textup{(Theorem \ref{thm:sz}(2)}\textup{)}.

We apply Burnside's lemma;  the cycle types of $S$ on the ovoid are classical (Suzuki \cite{suzuki1962};  the same input underlies Bradley's closed form, \cite{bradley2014}, Theorem 3.3.2).  For $g\in S$ let $\eta_3(g)=\binom{f}{3}+fc_2+c_3$ be the number of three-subsets fixed by $g$, where $f=\operatorname{fix}(g)$ and $c_i$ is the number of $i$-cycles of $g$ on the ovoid.  The class input of \textup{Theorem \ref{thm:sz}} gives:
(i) $g=1$:  $\eta_3(1)=\binom{q^2+1}{3}$;
(ii) an involution (a nonidentity element of a Sylow $2$-subgroup $Q$ of order $q^2$, lying in the point stabilizer of its unique fixed point) fixes one point and has cycle type $1^12^{q^2/2}$:  the only fixed three-subsets are $\{p,x,y\}$ with $p$ the fixed point and $\{x,y\}$ a $2$-cycle, so $\eta_3=\binom{1}{3}+1\cdot\frac{q^2}{2}=\frac{q^2}{2}$;
(iii) an element of order $4$ fixes one point and has no $2$- or $3$-cycle:  $\eta_3=0$;
(iv) an element of $H_0$-type (order $m>1$, $m\mid q-1$) fixes two points and has no $2$- or $3$-cycle (since $m$ is odd and $3
\nmid q-1$):  $\eta_3=\binom{2}{3}=0$;
(v) an element of $H_{\pm}$-type (order $m$, $m\mid q\pm r+1$, $r^2=2q$) fixes no point:  $\eta_3=0$.
The class sizes enter through the class weights $1/|S|$, $1/q^2$, $1/q$, $1/(2(q-1))$, $1/(4(q\pm r+1))$ of \cite{bradley2014}, Theorem 3.3.2;  only the identity and the involutions contribute:
\[
\sigma_3(S)
=\frac{1}{q^2(q-1)(q^2+1)}\binom{q^2+1}{3}
+\frac{1}{q^2}\cdot\frac{q^2}{2}
=\frac{q+1}{6}+\frac{1}{2}
=\frac{q+4}{6}.
\]
For $q=8$ this gives $\sigma_3(Sz(8))=2$, in agreement with \textup{Proposition \ref{prop:sz8-computed}} and \textup{Table \ref{tab:verify}}.

\label{rem:sz-field-examples}
Theorem \ref{thm:suzuki-field-final} gives $\sigma_3(Sz(8){:}3)=2$:  the identity fixes $\frac{8-2}{6}=1$ generic orbit and the two non-trivial field automorphisms have $d=1$, $n=3$, hence $\varepsilon=2^{1-1}=1$ each, so $t_F=(1+1+1)/3=1$, in agreement with \textup{Proposition \ref{prop:sz8-computed}}.  For $Sz(32){:}5$ the four non-trivial field automorphisms have $d=1$ and $3
\nmid n=5$, hence $\varepsilon=0$, and $t_F=5/5=1$, so $\sigma_3(Sz(32){:}5)=2$.  For $Sz(512){:}9$ ($a=9$):  the identity fixes $\frac{512-2}{6}=85$ generic orbits, the six elements of order $9$ have $d=1$ and $3\mid n=9$, fixing $2^{1-1}=1$ each, and the two elements of order $3$ have $d=3$ and $3\mid n=3$, fixing $2^{3-1}=4$ each, so $t_F=(85+6\cdot1+2\cdot4)/9=11$ and $\sigma_3(Sz(512){:}9)=12$.  The values for $q=8$ and $q=32$ are confirmed by the machine computations of \textup{Chapter \ref{sec:verify}} \textup{(Table \ref{tab:verify})}:  $\sigma_3(Sz(32))=6$ and $\sigma_3(Sz(32){:}5)=2$;  the degree of $Sz(512){:}9$ is $262145$, beyond direct machine enumeration, and the displayed value is the arithmetic output of the closed form.

\label{thm:ree}
Let $S=Ree(q)={}^2G_2(q)$, $q=3^{2m+1}>3$, act in its standard $2$-transitive action of degree $q^3+1$, and let $\mathcal{O}$ be a $3$-subset of the Ree unital \textup{(}$v=q^3+1$\textup{)}.
\begin{enumerate}
\item For every three-point orbit with representative $\mathcal{O}$, $S_{\mathcal{O}}\le S_3$ after quotienting by the pointwise stabilizer;  if the pointwise stabilizer is trivial, then
\[
|S_{\mathcal{O}}|\in\{1,2,3,6\}.
\]
\item For each computed value of $q$, the actual orbit data are those listed in \textup{Table \ref{tab:verify}}.
\end{enumerate}

\label{lem:ree-count}
Let $S={}^2G_2(q)$, $q=3^{2m+1}>3$, act on the Ree unital, fix two points $u,v$, and let $L'$ be the block fixed pointwise by the transposition $\tau\in S_{\{u,v\}}$.  We take as standing assumptions the dihedral structure $S_{\{u,v\}}\cong D_{2(q-1)}$ and the suborbit decomposition of \textup{Lemma \ref{lem:ree-dihedral}}, and the trivial pointwise stabilizer of every non-collinear triple of \textup{Lemma \ref{lem:ree-pointwise}}.  Then, among the $S_{\{u,v\}}$-orbits on the remaining points:
\begin{enumerate}
\item exactly $q$ of the paired orbits contain a point $x$ with $(13)$- or $(23)$-type transposition in $S_{\{u,v,x\}}$;
\item exactly $(q-1)/2$ of the paired orbits contain a point $x$ with a $3$-cycle in $S_{\{u,v,x\}}$;
\item exactly one of the $q+1$ invariant orbits (equivalently one $x\in L'$) has a $3$-cycle in $S_{\{u,v,x\}}$.
\end{enumerate}

\label{prop:ree-descent}
Let $S={}^2G_2(q)$, $q=3^{2m+1}>3$, act $2$-transitively on the Ree unital $\mathcal{P}$, let $\sigma$ be a field automorphism of order $f'\mid 2m+1$, and let $G=S\rtimes\langle\sigma\rangle\le\operatorname{Aut}(S)$, so that $G/S\cong C_{f'}$.  Put $q_0=3^{(2m+1)/f'}$.
\begin{enumerate}
\item[(i)] Every $\sigma$-invariant $S$-orbit on $\binom{\mathcal{P}}{3}$ contains a $\sigma$-fixed triple.  Equivalently, the $\sigma$-fixed $S$-orbits are precisely those meeting $\operatorname{Fix}_{\mathcal{P}}(\sigma)=\mathcal{P}(q_0)$, together with, when $3\mid f'$, the cycle-type orbits of the cubic subquotient (Remark \ref{rem:ree-descent-status}).
\item[(ii)] The number $A(f')$ of $\sigma$-fixed $S$-orbits is
\[
A(f')=
\begin{cases}
\dfrac{(q_0+3)^2}{6}=\sigma_3(Ree(q_0)),&3
\nmid f',\\[6pt]
\dfrac{q_0^2+2q_0+3}{2},&3\mid f'.
\end{cases}
\]
\end{enumerate}
The assertion (i) is unconditional for every $f'\mid 2m+1$ by the proof below \textup{(Lemma \ref{lem:ree-ext-cycles} covers $f'=3$;  the two arguments there and here agree)}.

\label{thm:ree-ext-reduction}
For ${}^2G_2(q)\le G\le\operatorname{Aut}({}^2G_2(q))$, $q=3^{2m+1}>3$, the classification of the $G$-orbits on three-subsets, together with all triple stabilizer orders and design parameters, is equivalent to:
\begin{enumerate}
\item the classification of the three-subset orbits of the Ree socle ${}^2G_2(q)$;  and
\item the induced action of $G/{}^2G_2(q)$ on the finite set of socle orbits.
\end{enumerate}
In particular, the action of a Ree almost simple overgroup on three-subsets reduces to the action of its outer quotient on the three-subset orbits of the Ree socle.  This reduction is the basis of \textup{Theorem \ref{thm:ree-ext}}:  once the number $a$ of $\sigma$-fixed $S$-orbits is known, every extension quantity follows from (R.1)--(R.5).  The fixed-orbit number is unconditional for every $f'\mid 2m+1$:  $a=(q_0^2+2q_0+3)/2$ for $3\mid f'$ \textup{(Lemma \ref{lem:ree-ext-cycles} for $f'=3$;  cubic reduction of Proposition \ref{prop:ree-descent}(ii) and Remark \ref{rem:ree-descent-status} for $f'\ge5$)}, and $a=(q_0+3)^2/6=\sigma_3(Ree(q_0))$ for $3
\nmid f'$ \textup{(Proposition \ref{prop:ree-descent}(ii)}.  Thus for $G=Ree(27){:}3$ one has $a=9$ and $\sigma_3(G)=56$ with the full stabilizer distribution $1^{35},2^8,3^7,6^3,9^1,18^2$;  the Ree extension formula is closed for every field quotient, including the previously open $f'=9,27$ \textup{(see Remark \ref{rem:ree-descent-status} for $\sigma_3(Ree(3^9)\cdot9)=7\,176\,734$)}.

\label{thm:alt}
For $n\ge5$ and $\mathcal{O}$ a $3$-subset of $\{1,\dots,n\}$:
\begin{align*}
S_{\mathcal{O}} &= Alt(n-3)\rtimes S_3, & |S_{\mathcal{O}}| &= 3\,(n-3)!,\\
Sym(n)_{\mathcal{O}} &= Sym(n-3)\rtimes S_3, & |Sym(n)_{\mathcal{O}}| &= 6\,(n-3)!,
\end{align*}
with pointwise stabilizers $Alt(n-3)$ and $Sym(n-3)$ respectively, and image $S_3$ in both cases.  For $n=4$:  $S=Alt(4)$ on $4$ points, $S_{\mathcal{O}}\cong C_3$ \textup{(}$|S_{\mathcal{O}}|=3$\textup{)};  $Sym(4)_{\mathcal{O}}=S_3$.

\label{lem:ext}
Let $S\lhd G\le\operatorname{Aut}(S)$, both $2$-transitive on $\mathcal{P}$ \textup{(}$|\mathcal{P}|\ge4$\textup{)}, $\mathcal{O}$ a $3$-subset.
\begin{enumerate}
\item $S_{\mathcal{O}}\le G_{\mathcal{O}}$ and $S_{(\mathcal{O})}\le G_{(\mathcal{O})}$.
\item The image $\overline{G}_{\mathcal{O}}$ contains $\overline{S}_{\mathcal{O}}$ and satisfies
$\overline{G}_{\mathcal{O}}/\overline{S}_{\mathcal{O}}\cong G_{\mathcal{O}}/(S_{\mathcal{O}}\cdot G_{(\mathcal{O})})$;  in particular
$|G_{\mathcal{O}}|\le |S_{\mathcal{O}}|\cdot|\operatorname{Out}(S)|$.
\item If $G_{\mathcal{O}}=G_{(\mathcal{O})}\rtimes\overline{G}_{\mathcal{O}}$ and the outer automorphism group acts on the three-point orbits, then the $G$-orbits on $\binom{\mathcal{P}}{3}$ are unions of $S$-orbits, with at most $|\operatorname{Out}(S)|$ orbits of each $S$-type.
\end{enumerate}

\label{lem:affine}
Let $G=V\rtimes G_0$ as above, $\mathcal{O}=\{0,u,w\}$.  An element $(v,g_0)\in G$ lies in $G_{\mathcal{O}}$ iff $g_0$ and $v$ satisfy one of the following:
\begin{enumerate}
\item[\textup{\textup{(}T0\textup{)}}] \emph{fixed point $0$, swap $u\leftrightarrow w$}:  $v=0$, $g_0\in G_0$, $g_0(u)=w$, $g_0(w)=u$  \textup{(}a transposition fixing $0$;  if additionally $g_0(u)=u$ and $g_0(w)=w$, then $g_0\in G_{(\mathcal{O})}$\textup{)};
\item[\textup{\textup{(}T1\textup{)}}] \emph{fixed point $u$}:  $v=w$, $g_0(w)=-w$, $g_0(u)=u-w$;
\item[\textup{\textup{(}T2\textup{)}}] \emph{fixed point $w$}:  $v=u$, $g_0(u)=-u$, $g_0(w)=w-u$;
\item[\textup{\textup{(}C\textup{)}}] \emph{$3$-cycle} $(0\mapsto u\mapsto w\mapsto0)$:  $v=u$, $g_0(u)=w-u$, $g_0(w)=-u$;
\item[\textup{\textup{(}I\textup{)}}] identity:  $v=0$, $g_0=\mathrm{id}$ \textup{(}fixes all three points\textup{)}.
\end{enumerate}
In particular:
\begin{enumerate}
\item The pointwise stabilizer is $G_{(\mathcal{O})}=\{g_0\in G_0: g_0(u)=u,\ g_0(w)=w\}$.
\item A transposition fixing $0$ exists iff $G_0$ contains an element swapping $u$ and $w$;  a transposition fixing $u$ exists iff $G_0$ contains an element with $g_0(u)=u-w,\ g_0(w)=-w$;  a $3$-cycle exists iff $G_0$ contains an element with $g_0(u)=w-u,\ g_0(w)=-u$.
\item If $g_0$ satisfies \textup{(}C\textup{)}, then the affine element $(u,g_0)$ permutes $\{0,u,w\}$ as the $3$-cycle $(0\,u\,w)$;  in particular $g_0^3$ acts as the identity on the plane $\langle u,w\rangle$.
\end{enumerate}

\label{rem:anharmonic}
For $AGL(1,q)$ the triples are conveniently parametrized as $\mathcal{O}_r=\{0,1,r\}$ with $r\in\mathbb{F}_q\setminus\{0,1\}$:  two triples lie in the same $AGL(1,q)$-orbit iff their parameters lie in the same \emph{anharmonic sextuple}
\[
r,\quad 1-r,\quad r^{-1},\quad (1-r)^{-1},\quad \frac{r}{r-1},\quad \frac{r-1}{r}.
\]
The transposition case is exactly the double coincidence of the sextuple (the midpoint configuration), the $3$-cycle case is exactly $r^2-r+1=0$ \textup{(equivalent to $r=a+1$, $a^2+a+1=0$ of \textup{Theorem \ref{thm:agl1}}(3)}\textup{)}, and the image $S_3$ occurs only in the characteristic-$3$ arithmetic-progression case.  Under $A\string\Gamma L(1,q)=V\rtimes(\mathbb{F}_q^{\times}\rtimes C_f)$ the orbit-fusion criterion is the complete one:  two triples $\mathcal{O}_r,\mathcal{O}_s$ lie in the same $A\string\Gamma L(1,q)$-orbit iff
\[
s\in\bigl\{\sigma(r),\ 1-\sigma(r),\ \sigma(r)^{-1},\ (1-\sigma(r))^{-1},\ \tfrac{\sigma(r)}{\sigma(r)-1},\ \tfrac{\sigma(r)-1}{\sigma(r)}\bigr\}
\]
for some $\sigma\in C_f$;  equivalently, for every $\sigma\in C_f$ and every $\pi\in S_3$, an element inducing $\pi$ on $\mathcal{O}_r$ exists iff $\sigma(r)=h_\pi(r)$, where $h_\pi$ ranges over the six anharmonic transformations.  \textup{(This replaces the informal statement that field automorphisms realize a transposition or a $3$-cycle;  it is the complete orbit-fusion criterion.)}

For the designs:  for a $2$-transitive $G$ and an orbit $\mathcal{B}=\mathcal{O}^G$ on triples with $s=|G_{\mathcal{O}}|$, the orbit design has $b=|G|/s$ blocks and replication parameter $\lambda=6b/(v(v-1))$ \textup{(\eqref{eq:lambda})}.  For $AGL(1,q)$ this gives $b=q(q-1)/s$ and $\lambda=6/s$ with $s\in\{1,2,3,6\}$;  for $A\string\Gamma L(1,q)=V\rtimes(\mathbb{F}_q^{\times}\rtimes C_f)$ it gives $b=q(q-1)f/s$ and $\lambda=6f/s$.  These parameters are automatically integral, and the blocks are distinct three-subsets \textup{(the designs are simple)}.  For the flag-transitivity claims in the applications \textup{(Chapter \ref{sec:design})}:  a design obtained from a 2-transitive group's triple orbit is automatically point-2-transitive and block-transitive;  flag-transitivity for $G$ itself requires $G_{\mathcal{O}}$ to be transitive on $\mathcal{O}$, equivalently the induced stabilizer $\overline{G}_{\mathcal{O}}$ is $C_3$ or $S_3$.  One must not assert $G$-flag-transitivity for every orbit design indiscriminately.  Also, when the orbit $\mathcal{O}^G$ is generated by applying all $g\in G$ to a representative $\mathcal{O}$, the resulting multiset must be deduplicated \textup{(the blocks are distinct three-subsets)};  the design parameters above already count distinct blocks.

\label{thm:affine-classical}
Let $\mathcal{O}=\{0,u,w\}$ with $u,w$ linearly independent, and $G_0\supseteq H$.
\begin{enumerate}
\item \textbf{Pointwise stabilizer} $G_{(\mathcal{O})}=G_0{}_{u,w}$, the pointwise stabilizer of $u,w$ in $G_0$ \textup{(when $G_0$ is a proper overgroup of $H$ this may be strictly larger than $H_{u,w}$:  a field or diagonal part may contribute elements fixing $u,w$;  we record $H_{u,w}$ as the contribution of the subgroup $H$ below}\textup{)}:
  \begin{enumerate}
  \item $H=\operatorname{SL}(n,q)$, $n\ge3$:  choosing a basis with $u=e_1$, $w=e_2$, the elements of $H_{u,w}$ have the block form $\left(\begin{smallmatrix}I_2&A\\0&B\end{smallmatrix}\right)$ with $B\in\operatorname{SL}(n-2,q)$ and $A\in M_{2\times(n-2)}(\mathbb{F}_q)$ arbitrary \textup{(}$2(n-2)$ free parameters\textup{)};  hence $H_{u,w}\cong q^{2(n-2)}:\operatorname{SL}(n-2,q)$ of order $q^{2(n-2)}|\operatorname{SL}(n-2,q)|$.  For $n=2$:  $H_{u,w}=1$.
  \item $H=Sp(2a,q)$:  the pointwise stabilizer depends on whether $\langle u,w\rangle$ is nondegenerate or totally isotropic.  If $\beta(u,w)
\ne 0$ \textup{(}nondegenerate plane\textup{)}, then $V=\langle u,w\rangle\perp\langle u,w\rangle^{\perp}$ and $H_{u,w}\congSp(2a-2,q)$, of order $|Sp(2a-2,q)|$ \textup{(extend by the identity on the perpendicular complement}\textup{)}.  If $\beta(u,w)=0$ \textup{(}totally isotropic plane\textup{)}, then $a\ge2$ and the pointwise stabilizer of the ordered pair $(u,w)$ has the closed form $|H_{u,w}|=q^{4a-5}|Sp(2a-4,q)|$ \textup{(convention $Sp(0,q)=1$;  the ordered totally isotropic pairs number $(q^{2a}-1)(q^{2a-1}-q)$, so the orbit--stabilizer formula gives $|H_{u,w}|=|Sp(2a,q)|/\bigl((q^{2a}-1)(q^{2a-1}-q)\bigr)=q^{4a-5}|Sp(2a-4,q)|$}\textup{)};  the induced image is $S_3$ for every $q$ \textup{(Remark \ref{rem:sp-isotropic}}\textup{)}.
  \item $H=G_2'(q)$ \textup{(}$p=2$\textup{)}:  $H_{u,w}$ is the pointwise stabilizer of $u,w$ in the natural module $\mathbb{F}_q^6$.  For $q=2^f\ge4$ a closed form is proved in \textup{Theorem \ref{thm:g2-classical}}:  $|H_{u,w}|=q(q^2-1)$ if $h(u,w)
\ne 0$ \textup{(}the spanned $2$-space is nondegenerate for the alternating form $h$ of $Sp(6,q)$\textup{)}, and $|H_{u,w}|=q^5$ or $q^3$ if $h(u,w)=0$ \textup{(}the spanned $2$-space is totally isotropic, of long-root resp.\ short-root type in the $G_2$ hexagon geometry, cf.\ \cite{cooperstein1979}\textup{)}.  For $q=2$ ($2^6{:}G_2'(2)\cong2^6{:}PSU(3,3)$, $v=64$, \textup{Table \ref{tab:verify}}\textup{)} the orbit data are $r=3$ with $\lambda=32,24,6$;  $q=2$ is exceptional and is not covered by the general $q$ statement of \textup{Theorem \ref{thm:g2-classical}}.
  \end{enumerate}
\item \textbf{$3$-cycles always exist}:  for every independent pair $(u,w)$ there is $g_0\in H$ with $g_0(u)=w-u$, $g_0(w)=-u$.  Indeed the matrix of $g_0$ in the basis $(u,w)$ is $M=\begin{pmatrix}-1 & -1\\ 1 & 0\end{pmatrix}$ of determinant $1$;  for $H=Sp(2a,q)$ it preserves the alternating form on $\langle u,w\rangle$ and extends to $Sp(2a,q)$ in both plane types \textup{(Remark \ref{rem:sp-isotropic})}, and for $G_2'(q)\leSp(6,q)$ the element exists by the same symplectic computation.
\item \textbf{Transpositions}:  a transposition fixing $0$ \textup{(}swap $u\leftrightarrow w$\textup{)} exists iff $H$ contains an element with $g_0(u)=w,\ g_0(w)=u$;  a transposition fixing $u$ exists iff $H$ contains $g_0$ with $g_0(u)=u-w,\ g_0(w)=-w$ \textup{(}matrix $\begin{pmatrix}1&0\\ -1&-1\end{pmatrix}$, det $1$\textup{)};  fixing $w$:  matrix $\begin{pmatrix}-1&-1\\0&1\end{pmatrix}$.  Concretely:
  \begin{enumerate}
  \item $H=\operatorname{SL}(n,q)$, $n\ge3$:  all transposition types exist for all $q$ \textup{(}the $2\times2$ blocks above have determinant $1$, and the complement is adjusted by an element of $\operatorname{SL}(n-2,q)$\textup{)};
  \item $H=\operatorname{SL}(2,q)$:  transpositions exist iff $q$ is even \textup{(}then $-1=1$ and the swap $\begin{pmatrix}0&1\\1&0\end{pmatrix}$ has determinant $-1=1$\textup{)};  for $q$ odd:  no transposition of any kind;
  \item $H=Sp(2a,q)$, nondegenerate case:  transpositions exist iff $q$ is even \textup{(}the swap on $\langle u,w\rangle$ has determinant $-1$, and it preserves $\beta$ iff $\beta(w,u)=\beta(u,w)$, i.e.\ iff the characteristic is $2$\textup{)};  in the totally isotropic case transpositions exist for every $q$ \textup{(Remark \ref{rem:sp-isotropic}}\textup{)};
  \item $H=G_2'(q)$ \textup{(}$p=2$\textup{)}:  transpositions exist.
  \end{enumerate}
\item \textbf{Summary} \textup{(}generic non-collinear triples\textup{)}:
  {\footnotesize\setlength{\tabcolsep}{4pt} 
  \begin{center}
  \begin{tabular}{llll}
  \toprule
  $H$ & image $\overline{G}_{\mathcal{O}}$ & kernel & $|G_{\mathcal{O}}|$ \\
  \midrule
  $\operatorname{SL}(n,q)$, $n\ge3$ & $S_3$ & $q^{2(n-2)}|\operatorname{SL}(n-2,q)|$ & $6\,q^{2(n-2)}|\operatorname{SL}(n-2,q)|$ \\
  $\operatorname{SL}(2,q)$, $q$ even & $S_3$ & $1$ & $6$ \\
  $\operatorname{SL}(2,q)$, $q$ odd & $C_3$ & $1$ & $3$ \\
  $Sp(2a,q)$, $q$ even, nondeg. & $S_3$ & $Sp(2a-2,q)$ & $6|Sp(2a-2,q)|$ \\
  $Sp(2a,q)$, $q$ odd, nondeg. & $C_3$ & $Sp(2a-2,q)$ & $3|Sp(2a-2,q)|$ \\
  $Sp(2a,q)$, totally isotr. & $S_3$ & $q^{4a-5}|Sp(2a-4,q)|$ & $6q^{4a-5}|Sp(2a-4,q)|$ \\
  $G_2'(q)$, $q$ even & $S_3$ & $q(q^2-1)$;  $q^5$;  $q^3$ & $6q(q^2-1)$;  $6q^5$;  $6q^3$ \\
  \bottomrule
  \end{tabular}
  \end{center}}
  for the symplectic rows:  the nondegenerate rows with $\beta(u,w)
\ne 0$ have kernel $Sp(2a-2,q)$;  the totally isotropic row has kernel $q^{4a-5}|Sp(2a-4,q)|$ \textup{(Remark \ref{rem:sp-isotropic})}.  For the $G_2'$ row the three kernel values $q(q^2-1)$, $q^5$, $q^3$ correspond respectively to the hyperbolic class ($h(u,w)
\ne 0$) and to the long-root resp.\ short-root isotropic classes ($h(u,w)=0$) of \textup{Theorem \ref{thm:g2-classical}}.  The two plane types form distinct orbits of $Sp(2a,q)$.  For the smallest case $ASp(4,2)=2^4{:}Sp(4,2)\cong2^4{:}S_6$ on $16$ points the non-collinear triples fall into two orbits with $|G_{\mathcal{O}}|=36$ \textup{(}kernel $6$, nondegenerate\textup{)} and $48$ \textup{(}kernel $8$, totally isotropic\textup{)}, both with image $S_3$, giving $\lambda=8$ and $6$ \textup{(\textup{Table \ref{tab:verify}}\textup{)}}.
\end{enumerate}

\label{rem:sp-isotropic}
For the symplectic rows the two plane types $\beta(u,w)
\ne 0$ and $\beta(u,w)=0$ form distinct $Sp(2a,q)$-orbits on independent pairs and must be kept apart.  The extension of a linear map on $\pi=\langle u,w\rangle$ to an element of $Sp(2a,q)$ is immediate when $\pi$ is nondegenerate \textup{(identity on $\pi^{\perp}$}\textup{)} but not when $\pi$ is totally isotropic;  in the latter case one completes $\{u,w\}$ to a hyperbolic basis $\{u,w,f_1,f_2\}$ with $\beta(u,f_1)=\beta(w,f_2)=1$ and all other pairings zero, and extends a $2\times2$ matrix $M$ on $\pi$ by $Z=(M^{\mathsf T})^{-1}$ on $\langle f_1,f_2\rangle$:  a direct multiplication gives $\left(\begin{smallmatrix}M&0\\0&Z\end{smallmatrix}\right)^{\mathsf T}\left(\begin{smallmatrix}0&I_2\\-I_2&0\end{smallmatrix}\right)\left(\begin{smallmatrix}M&0\\0&Z\end{smallmatrix}\right)=\left(\begin{smallmatrix}0&I_2\\-I_2&0\end{smallmatrix}\right)$, so the extension preserves the alternating form and has determinant $1$.  In particular the $3$-cycle matrix $M=\left(\begin{smallmatrix}-1&-1\\1&0\end{smallmatrix}\right)$ of \textup{Theorem \ref{thm:affine-classical}(2)} extends in both cases \textup{(}$\det M=1$\textup{)}, while the swap $P=\left(\begin{smallmatrix}0&1\\1&0\end{smallmatrix}\right)$ extends by $\mathrm{diag}(P,P)$, which is symplectic for every $q$:  thus, on the totally isotropic orbit, transpositions exist for all $q$ \textup{($a\ge2$}\textup{)}, whereas on the nondegenerate orbit they exist exactly for $q$ even.  For $q=2$ the isotropic values in \textup{Table \ref{tab:main}} are computed directly (\textup{e.g.\ $ASp(4,2)$:  $\lambda=8$ and $6$}), and the parabolic kernel order is not of the form $q^{2a-1}|Sp(2a-2,q)|$ in general.

\label{thm:g2-classical}
Let $q=2^{f}\ge4$ and $H=G_2'(q)=G_2(q)$ act on the natural module $V=\mathbb{F}_q^6$, with $H\leSp(6,q)$ preserving the alternating form $h$, and let $G=V\rtimes H$ act on the $v=q^6$ affine points \textup{(the $2$-transitive affine row of \textup{Table \ref{tab:hering}}}\textup{)}.
\begin{enumerate}
\item $H$ is transitive on the nonzero vectors, and the stabilizer of a nonzero vector is the maximal parabolic subgroup $H_u=q^5{:}\operatorname{SL}(2,q)$ of order $|H_u|=q^6(q^2-1)$ \textup{(classical:  cf.\ \cite{kleidmanliebeck};  the same value follows from $|H|=q^6(q^6-1)(q^2-1)$ and $|V\setminus\{0\}|=q^6-1$}\textup{)}.  Consequently $H_u$ fixes every point of the line $\langle u\rangle$ \textup{(by linearity}\textup{)}.
\item The orbits of $H_u$ on $V\setminus\{0,u\}$ are the following \textup{(the transitivity is part of the classical $G_2$ hexagon geometry, cf.\ \cite{cooperstein1979};  the sizes and stabilizer orders are then determined by the orbit--stabilizer identity, and the numerical data are verified for $q=4$ in \textup{Chapter \ref{sec:verify}}}\textup{)}:
  \begin{itemize}
  \item[(a)] the $q-2$ fixed points $\{\lambda u\}$, $\lambda\in\mathbb{F}_q^{\times}\setminus\{1\}$ \textup{(collinear points}\textup{)};
  \item[(b)] for each $c\in\mathbb{F}_q^{\times}$ the set $W_c=\{w\in V:\ h(u,w)=c\}$ \textup{(so $\langle u,w\rangle$ is a nondegenerate, hyperbolic $2$-space}\textup{)}, a single orbit of size $q^5$, with pointwise stabilizer order $|H_{u,w}|=q(q^2-1)$;
  \item[(c)] two orbits contained in $u^{\perp}\setminus\{0,u\}$ \textup{(so $\langle u,w\rangle$ is totally isotropic}\textup{)}:  the long-root class of size $q(q^2-1)$ with $|H_{u,w}|=q^5$, and the short-root class of size $q^3(q^2-1)$ with $|H_{u,w}|=q^3$.
  \end{itemize}
  The size check $q^5-q=q(q^2-1)+q^3(q^2-1)$ accounts for all isotropic non-collinear vectors.
\item \textbf{The three-subset orbits of $G$ on the affine points.}  $G$ has $r=q+1+c(q)$ orbits on three-subsets, with $c(q)=1+\frac{q-4}{6}$ if $3\mid q-1$ and $c(q)=\frac{q-2}{6}$ otherwise \textup{($q=2^f$;  the first case is $f$ even, the second $f$ odd)}:
  \begin{itemize}
  \item[(a)] \textbf{collinear} $\{0,u,\lambda u\}$:  the pointwise stabilizer of every collinear triple is $H_u$ of order $q^6(q^2-1)$;  the induced image in $S_3$ contains no transposition \textup{(a swap of $u$ and $\lambda u$ would be a linear map with $g(u)=\lambda u$, $g(\lambda u)=u$, forcing $\lambda^2=1$, i.e.\ $\lambda=1$ in characteristic $2$;  hence no transposition exists on the line}\textup{)}.  The collinear $G$-orbits are the orbits of $S_3\cong\langle s,i\rangle$ on $\mathbb{F}_q\setminus\{0,1\}$, where $s(\lambda)=\lambda+1$ and $i(\lambda)=\lambda^{-1}$ \textup{(the translation by $u$ moves the base point, and $\{0,u,\lambda u\}=\{0,\lambda u,u\}$}\textup{)}:
    \begin{itemize}
    \item if $3\mid q-1$ \textup{(}$f$ even\textup{)}:  one orbit $\{\omega,\omega^2\}$ with $\omega$ a primitive cube root, induced image $C_3$ \textup{(realized by the scalar $g=\omega^2$ on the line together with the translation by $u$}\textup{)}, $|G_{\mathcal{O}}|=3q^6(q^2-1)$ and $\lambda=2$;  and $\frac{q-4}{6}$ orbits with induced image $1$, $|G_{\mathcal{O}}|=q^6(q^2-1)$ and $\lambda=6$;
    \item if $3
\nmid q-1$ \textup{(}$f$ odd\textup{)}:  $\frac{q-2}{6}$ orbits, each with induced image $1$, $|G_{\mathcal{O}}|=q^6(q^2-1)$ and $\lambda=6$.
    \end{itemize}
    The block counts are consistent:  the collinear blocks number $\binom{q^6}{3}\cdot2/(q^6-2)=q^6(q^6-1)(q-2)/6$, which equals $|G|/\bigl(3q^6(q^2-1)\bigr)+\frac{q-4}{6}\cdot|G|/\bigl(q^6(q^2-1)\bigr)$ for $f$ even and $\frac{q-2}{6}\cdot|G|/\bigl(q^6(q^2-1)\bigr)$ for $f$ odd;  for $q=4$ this gives the single collinear orbit of size $5591040$ \textup{(Chapter \ref{sec:verify}}\textup{)}.
  \item[(b)] \textbf{hyperbolic} $\{0,u,w\}$ with $h(u,w)
\ne 0$:  $q-1$ orbits \textup{(one for each value of $h(u,w)=c$}\textup{)};  pointwise stabilizer of order $q(q^2-1)$, induced image $S_3$, $|G_{\mathcal{O}}|=6q(q^2-1)$;  $\lambda=q^5$;
  \item[(c)] \textbf{isotropic} $\{0,u,w\}$ with $h(u,w)=0$:  two orbits \textup{(long-root and short-root}\textup{)};  pointwise stabilizers of orders $q^5$ and $q^3$, induced image $S_3$ in both cases, $|G_{\mathcal{O}}|=6q^5$ resp.\ $6q^3$;  $\lambda=q(q^2-1)$ resp.\ $q^3(q^2-1)$.
  \end{itemize}
  \textup{(For the non-collinear orbits the affine stabilizer decomposes as $|G_{\mathcal{O}}|=6|H_{u,w}|$:  the elements of $G_{\mathcal{O}}$ are $(v,g)$ with $v\in\{0,u,w\}$, and for each such $v$ exactly two linear parts realize the corresponding permutation of $\{0,u,w\}$:  one sends $w$ to $u+w$ and one sends $u$ to $u+w$;  both occur, since $w$ and $u+w$ lie in the same $H_u$-orbit whenever $h(u,w)
\ne 0$ resp.\ in the isotropic class when $h(u,w)=0$, by (2).  The non-collinear count is $(q-1)+2$;  adding the collinear count $c(q)$ of the item above gives $r=q+1+c(q)$.  The orbit count $r$, the stabilizer orders and the injectivity of the suborbit correspondence are verified for $q=4$ in \textup{Chapter \ref{sec:verify}} (where $c(4)=1$ and $r=6=q+2$)}\textup{)}.
\end{enumerate}

\label{thm:affine-collinear}
Let $\mathcal{O}=\{0,u,\lambda u\}$ with $\lambda\in\mathbb{F}_q^{\times}\setminus\{1\}$ \textup{(}collinear triple\textup{)}, $H=\operatorname{SL}(2,q)\le G_0$ \textup{(}the other $H$ are analogous;  $G_2'(q)$ and $Sp(2a,q)$ with $q$ even behave like the $\operatorname{SL}(2,q)$-even row, cf.\ the verification table\textup{)}.
\begin{enumerate}
\item Pointwise stabilizer:  $G_{(\mathcal{O})}=H_u$, the vector stabilizer of $u$ in $H$;  for $H=\operatorname{SL}(2,q)$ this is the transvection subgroup of order $q$ \textup{(}for $G_0$ with full $\operatorname{GL}(2,q)$, $|G_{(\mathcal{O})}|=q(q-1)$\textup{)}.
\item On the line $\langle u\rangle$:
  \begin{enumerate}
  \item a transposition fixing $0$ \textup{(}swapping $u,\lambda u$\textup{)} exists iff $\lambda=-1$ and $-1$ is realized on the line:  for $H=\operatorname{SL}(2,q)$ the element $-I$ \textup{(}det $1$\textup{)} realizes it, so this holds for $q$ odd;  for $q$ even $\lambda=-1=1$ is excluded;
  \item a $3$-cycle exists iff $\lambda^2-\lambda+1=0$ is solvable in $\mathbb{F}_q$ \textup{(}i.e.\ $\lambda$ a primitive cube root of unity, $q\equiv1\pmod3$, or $\lambda=-1$ in characteristic $3$\textup{)};  the realizing element is $g_0=\mathrm{diag}(\lambda-1,\,-\lambda)$ \textup{(}det $=(\lambda-1)(-\lambda)=1$ since $\lambda(\lambda-1)=-1$\textup{)} together with the translation by $u$.
  \end{enumerate}
\item Consequently, for $H=\operatorname{SL}(2,q)$:
  {\footnotesize\setlength{\tabcolsep}{3pt} 
  \begin{center}
  \begin{tabular}{llll}
  \toprule
  $q$ & $|G_{\mathcal{O}}|$ & image & condition \\
  \midrule
  $q=2$ & 6 & $S_3$ & degree $4$:  all triples are non-collinear \textup{(}see \textup{Table \ref{tab:verify}}\textup{)} \\
  $q=3^f$ \textup{(char $3$)} & $q$ & $1$ & generic $\lambda$ \\
   & $6q$ & $S_3$ & $\lambda=-1=2$ \\
  $q$ odd, $q\ge5$, $\operatorname{char}\mathbb{F}_q\ne3$ & $q$ & $1$ & generic $\lambda$ \\
   & $2q$ & $C_2$ & $\lambda\in\{-1,2,\tfrac12\}$ \\
   & $3q$ & $C_3$ & $\lambda^2-\lambda+1=0$ \textup{(}$q\equiv1\pmod3$\textup{)} \\
  $q$ even, $q\ge4$ & $q$ & $1$ & generic $\lambda$ \\
   & $3q$ & $C_3$ & $\lambda$ a primitive cube root \textup{(}$q\equiv1\pmod3$\textup{)} \\
  \bottomrule
  \end{tabular}
  \end{center}}
  \textup{(In characteristic $3$, $\{-1,2,\tfrac12\}=\{2\}$ and $(-1)^2-(-1)+1=0$, so at $\lambda=-1$ both the transposition and the $3$-cycle are realized and the image is $S_3$ with $|G_{\mathcal{O}}|=6q$, whereas for generic $\lambda$ the image is trivial with $|G_{\mathcal{O}}|=q$;  verified for $q=9$ in \textup{Chapter \ref{sec:verify}}.)}
\end{enumerate}

\label{prop:aff729}
Let $\rho\colon\operatorname{SL}(2,13)\to\operatorname{GL}(6,3)$ be obtained from either of the two $6$-dimensional faithful irreducible $\mathbb{F}_3$-modules of $\operatorname{SL}(2,13)$, and let $G=3^6\rtimes\rho(\operatorname{SL}(2,13))$ act on the points of $V=\mathbb{F}_3^6$ \textup{(}$v=729$\textup{)}.  Then $|G|=3^6|\operatorname{SL}(2,13)|=1592136$, $G$ is $2$-transitive on $V$, and $G$ has exactly $44$ orbits on the three-point subsets of $V$:
\begin{itemize}
\item[(a)] one orbit with $\lambda=1$:  orbit size $88452$, $|G_{\mathcal{O}}|=18$, pointwise stabilizer of order $3$ and image $S_3$;  the corresponding simple design is a $2$-$(729,3,1)$ Steiner triple system;
\item[(b)] four orbits with $\lambda=6$:  orbit size $530712$, $|G_{\mathcal{O}}|=3$;  for three of them the pointwise stabilizer is trivial and the image is $C_3$, and for one the pointwise stabilizer has order $3$ and the image is trivial;
\item[(c)] thirty-nine orbits with $\lambda=18$:  orbit size $1592136$, $|G_{\mathcal{O}}|=1$.
\end{itemize}
The orbit sizes sum to $\binom{729}{3}=64304604$;  the Burnside count on three-subsets gives $44$ orbits and the count on ordered triples gives $247$;  and $\lambda=6|G|/\bigl(|G_{\mathcal{O}}|\,v(v-1)\bigr)$ \eqref{eq:lambda} holds on every orbit.

